  async function setting(key,value){if(state.editing){state.officeDraft={...effectiveOffice(),[key]:value};state.scene?.update(sceneData());return;}await saveLayout(current=>({...current,[key]:value}));render();}
  let layoutQueue=Promise.resolve();
  function saveLayout(input){const generation=state.generation;const pending=layoutQueue.catch(()=>{}).then(()=>commitLayout(input,generation));layoutQueue=pending;return pending;}
  async function commitLayout(input,generation){
    if(generation!==state.generation||!state.data)return false;const previous=state.data.office,layout=typeof input==='function'?input(previous):input;const revision=typeof input==='function'?previous.revision:(layout.revision??previous.revision);state.data.office={...layout,revision};
    try{const result=await api('/layout',{...layout,revision},'PUT');if(generation!==state.generation||!state.data)return;state.data.office=result.office;state.scene?.update(sceneData());return true;}
    catch(err){if(generation!==state.generation||!state.data)return;state.data.office=previous;state.error=errorText(err);showError();state.scene?.update(sceneData());return false;}
  }
  async function send(ids=null,workflow=null,evidence=null){
    if(state.busy||!state.draft.trim()||!profile())return;
    const conversation=state.data.conversations.find(item=>item.id===state.conversationId),participants=ids || conversation?.profileIds || [state.selected];
    const owner=state.generation;const task=state.draft;state.draft='';state.busy=true;state.progress=L('İlgili hafıza ve veri hazırlanıyor…','Preparing relevant memory and data…');state.controller=new AbortController();state.error='';state.live='';render();
    const optimistic={id:'pending',role:'user',text:task,createdAt:new Date().toISOString()};state.messages.push(optimistic);paintMessages();
    state.data.activeJobs=[...(state.data.activeJobs || []),{id:'pending',profileIds:workflow?[participants[0]]:participants,phase:'review'}];state.scene?.react(participants);state.scene?.update(sceneData());
    try{
      const result=await root.BuyerLogAI.runAgentOffice({workflow:!!workflow,evidence:!!evidence,payload:{...(evidence?{attachmentIds:evidence.selected.map(f=>f.id),fingerprint:evidence.fingerprint,confirmed:true}:{}),...(workflow?{fingerprint:workflow.fingerprint,confirmed:true,rounds:workflow.rounds}:{}),profileIds:participants,conversationId:ids?'':state.conversationId,task,scope:state.scope,mode:state.mode,lang:en()?'en':'tr'},signal:state.controller.signal,
        onProgress:event=>{if(owner!==state.generation)return;if(workflow&&event.profileIds){state.data.activeJobs=(state.data.activeJobs||[]).map(j=>j.id==='pending'?{...j,profileIds:event.profileIds,phase:event.delta?'responding':'review'}:j);state.scene?.update(sceneData());if(event.index!==state.workflowStep){state.workflowStep=event.index;state.live='';}state.progress=L('Koordineli adım','Coordinated step')+' '+(Number(event.index)+1)+'/'+event.total;}if(event.delta){state.data.activeJobs=(state.data.activeJobs||[]).map(job=>job.id==='pending'?{...job,phase:'responding'}:job);state.scene?.update(sceneData());state.live+=event.delta;state.progress=L('Yanıt hazırlanıyor…','Preparing the answer…');}else if(!workflow)state.progress=event.phase==='sending'?L('LCW AI değerlendiriyor…','LCW AI is reviewing…'):L('İş yürütülüyor…','Job is running…');const p=host()?.querySelector('[data-ao-progress]');if(p)p.textContent=state.progress;}});
      if(owner!==state.generation)return;state.conversationId=result.conversation.id;state.messages=state.messages.filter(item=>item.id!=='pending');state.messages.push(result.message);
      state.progress=L('Yanıt ve konuşma arşivlendi.','The answer and conversation were archived.');
    }catch(err){if(owner!==state.generation)return;state.error=errorText(err);state.progress='';}
    finally{if(owner!==state.generation)return;state.busy=false;state.controller=null;state.live='';await refresh();if(state.conversationId){const value=await api(`/conversations/${state.conversationId}/messages`);state.messages=value.messages;state.hasMore=value.hasMore;state.before=value.before;}else state.messages=state.messages.filter(item=>item.id!=='pending');render();}
  }
  function paintMessages(){const box=host()?.querySelector('.aoMessages');if(box){box.innerHTML=state.messages.map(item=>message(item)).join('');box.scrollTop=box.scrollHeight;}}
  async function evidenceDialog(){const raw={profileIds:[state.selected],scope:state.scope,task:state.draft};const {preview}=await api('/evidence/preview',raw);dialog(L('Yetkili kalite belgeleri','Authorized quality documents'),`<p class="aoNote">${esc(L('Önce sipariş veya PLM kapsamını seçin. En fazla beş belge; dosya başına 19 MiB güvenli sınırı. Belgeler yalnız ortak LCW AI motoruna yüklenir.','First select the order or PLM scope. Up to five documents; 19 MiB safety limit per file. Documents upload only through the common LCW AI engine.'))}</p>${preview.choices.map(f=>`<label><input type="checkbox" name="document" value="${esc(f.id)}">${esc(f.name)} · ${esc(bytes(f.size))}</label>`).join('')||empty(L('Bu kapsamda erişilebilir belge yok.','No accessible documents in this scope.'))}<label>${esc(L('İnceleme talebi','Review request'))}<textarea name="task" class="aoInput" rows="4" maxlength="4000">${esc(state.draft)}</textarea></label>`,async modal=>{const result=await api('/evidence/preview',{...raw,task:value(modal,'task'),attachmentIds:[...modal.querySelectorAll('[name="document"]:checked')].map(e=>e.value)});if(!result.preview.selected.length||!result.preview.task)throw{code:'OFFICE_TASK_INVALID'};deferDialog(()=>evidenceConfirm(result.preview));},L('Kapsam ve maliyeti gör','Preview scope and cost'));}
  function evidenceConfirm(plan){dialog(L('Belge inceleme onayı','Document review approval'),`<p>${esc(plan.task)}</p><p class="aoNotice">${esc(bytes(plan.bytes))} · ${plan.uploadCalls} ${esc(L('dosya yükleme','file uploads'))} + ${plan.analysisCalls} ${esc(L('AI analiz çağrısı','AI analysis call'))}</p>${plan.selected.map(f=>`<p>${esc(f.name)} · ${esc(bytes(f.size))}</p>`).join('')}<p class="aoNote">${esc(L('Yükleme, modelin her sayfayı eksiksiz okuduğunu kanıtlamaz. Çıktı öneridir; onay ve kaynak verisi otomatik değişmez.','Uploading does not prove the model read every page completely. Output is a proposal; approvals and source data are not changed automatically.'))}</p><label><input name="confirm" type="checkbox">${esc(L('Seçili belgeleri ve çağrıları onaylıyorum','I approve the selected documents and calls'))}</label>`,async modal=>{if(!checked(modal,'confirm'))throw{code:'OFFICE_APPROVAL_REQUIRED'};state.draft=plan.task;state.scope=plan.scope;root.BLLayerSystem?.closeDialog?.(modal);modal.remove();state.pane='office';await send(plan.profileIds,null,plan);},L('İncele','Review'));}
