  function assistantDialog(){const prefs=state.data.assistant;dialog(L('Proaktif asistan','Proactive assistant'),`<p class="aoNote">${esc(L('Ofise girmeden bütün yetkili alanlarını izler. Risk ve günlük özet hesapları AI çağırmaz. Büyük arşiv incelemesi ayrı önizleme/onay gerektirir.','Monitors your authorized areas without opening the office. Risk checks and daily briefs make no AI calls. Large archive review requires a separate preview and approval.'))}</p><label><input name="enabled" type="checkbox" ${prefs.enabled?'checked':''}>${esc(L('Proaktif uyarılar','Proactive alerts'))}</label><label>${esc(L('Kontrol aralığı (dakika)','Check interval (minutes)'))}<input class="aoInput" name="intervalMinutes" type="number" min="2" max="30" value="${prefs.intervalMinutes}"></label><label>${esc(L('Günlük özet saati (yerel)','Daily brief hour (local)'))}<input class="aoInput" name="dailyHour" type="number" min="0" max="23" value="${prefs.dailyHour}"></label><label>${esc(L('Uyarı eşiği','Alert threshold'))}<select class="aoInput" name="severity">${['HIGH','MEDIUM','WATCH'].map(k=>`<option ${prefs.severity===k?'selected':''}>${k}</option>`).join('')}</select></label>${root.buyerLogDesktop?.agentBackground?`<label><input name="desktopBackground" type="checkbox" ${prefs.desktopBackground?'checked':''}>${esc(L('Pencereyi kapatınca sistem tepsisinde takibe devam et','Continue monitoring in the tray when the window closes'))}</label><p class="aoNote">${esc(L('Tepsiden Çıkış seçildiğinde takip durur. Bilgisayar kapalıyken veya uygulama tamamen kapatıldığında çalışmaz.','Choosing Quit in the tray stops monitoring. It cannot run while the computer is off or the application has fully exited.'))}</p>`:''}`,async modal=>{const result=await api('/assistant',{revision:prefs.revision,enabled:checked(modal,'enabled'),desktopBackground:root.buyerLogDesktop?.agentBackground?checked(modal,'desktopBackground'):prefs.desktopBackground,intervalMinutes:Number(value(modal,'intervalMinutes')),dailyHour:Number(value(modal,'dailyHour')),severity:value(modal,'severity'),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone},'PUT');state.data.assistant=result.assistant;await root.BLAgentNotifications?.refresh();},L('Kaydet','Save'));}
  function coordinatedDialog(){dialog(L('Agent koordinasyonu','Agent coordination'),
    `<p class="aoNote">${esc(L('Her agent ayrı LCW AI çağrısında çalışır. Gerçek yanıtlar sıradaki agenta kanıt olarak aktarılır; son adım ortak sonuç üretir. Aynı model kullanılır, bağımsız dış denetim sayılmaz.','Each agent runs in a separate LCW AI call. Actual replies are passed to the next agent as evidence; the final step synthesizes the result. The same model is used; this is not an independent external review.'))}</p>${state.data.profiles.map(a=>`<label><input type="checkbox" name="participant" value="${esc(a.id)}" ${a.id===state.selected?'checked':''}>${esc(a.name)} · ${esc(a.role)}</label>`).join('')}<label>${esc(L('Görev','Task'))}<textarea class="aoInput" name="task" rows="4" maxlength="4000">${esc(state.draft)}</textarea></label><label>${esc(L('Tur','Rounds'))}<select class="aoInput" name="rounds"><option value="1">${esc(L('Analiz + ortak sonuç','Analysis + synthesis'))}</option><option value="2">${esc(L('Analiz + karşılıklı inceleme + ortak sonuç','Analysis + mutual review + synthesis'))}</option></select></label>`,
    async modal=>{const raw={profileIds:[...modal.querySelectorAll('[name="participant"]:checked')].map(el=>el.value),task:value(modal,'task'),scope:state.scope,rounds:Number(value(modal,'rounds'))};const result=await api('/workflow/preview',raw);deferDialog(()=>coordinationConfirm(result.preview));},L('Adımları ve maliyeti gör','Preview steps and cost'));}
  function coordinationConfirm(plan){dialog(L('Koordineli görev önizlemesi','Coordinated task preview'),`<p>${esc(plan.task)}</p><p class="aoNotice">${plan.calls} ${esc(L('LCW AI çağrısı · sırayla çalışır · kaynak verisi değişmez','LCW AI calls · sequential execution · source data is unchanged'))}</p><ol>${plan.steps.map(s=>`<li>${esc(s.name)} · ${esc(s.kind==='review'?L('Karşılıklı inceleme','Mutual review'):s.kind==='synthesis'?L('Ortak sonuç','Synthesis'):L('Analiz','Analysis'))}</li>`).join('')}</ol><label><input type="checkbox" name="confirm">${esc(L('Bu adımları ve çağrı sayısını onaylıyorum','I approve these steps and the call count'))}</label>`,async modal=>{if(!checked(modal,'confirm'))throw{code:'OFFICE_APPROVAL_REQUIRED'};state.draft=plan.task;state.scope=plan.scope;state.pane='office';root.BLLayerSystem?.closeDialog?.(modal);modal.remove();await send(plan.profileIds,plan);},L('Koordinasyonu başlat','Start coordination'));}
  function sharedDialog(){dialog(L('Ortak görev · tek analiz, ayrı bakışlar','Shared job · one analysis, separate perspectives'),
    `<p class="aoNote">${esc(L('En fazla dört agent seç. Buyer Log ilgili hafızaları tek bağlamda toplar; AI her agent için ayrı bakış verir. Bu, bağımsız denetim değildir.','Select up to four agents. Buyer Log combines relevant memories into one context; AI gives a perspective for each agent. This is not an independent review.'))}</p>${state.data.profiles.map(agent=>`<label><input type="checkbox" name="participant" value="${esc(agent.id)}" ${agent.id===state.selected?'checked':''}>${esc(agent.name)} · ${esc(agent.role)}</label>`).join('')}<label>${esc(L('Görev','Task'))}<textarea class="aoInput" name="task" rows="4" maxlength="4000">${esc(state.draft)}</textarea></label>`,
    async modal=>{const ids=[...modal.querySelectorAll('[name="participant"]:checked')].map(el=>el.value);if(!ids.length||ids.length>4||!value(modal,'task').trim())throw{code:'OFFICE_TASK_INVALID'};state.draft=value(modal,'task');state.pane='office';modal.remove();await send(ids);},L('Ortak işi başlat','Start shared job'));}
  async function scan(offset=0){const result=await api('/scan',{scope:state.scope,offset,limit:50,force:offset===0});state.analysis=result.analysis;state.analysisOffset=offset;state.pane='actions';render();}
  async function archiveDialog(ownerId='',profileId='',range={}){
    const request={ownerId:ownerId || undefined,profileIds:profileId?[profileId]:[state.selected],...range},preview=(await api('/training/preview',request)).preview;
    state.archivePreview={...preview,request};
    const body=`<p>${preview.records} ${esc(L('kayıt','records'))} · ${esc(bytes(preview.bytes))} · ${preview.parts.length} ${esc(L('dosya parçası','file parts'))}</p>
      <p class="aoNote">${esc(L('Parçalar 20 MB sınırının altında kalır; mesaj kimliği ve tarihi korunur. Dosyanın yüklenmesi bütün içeriğin model tarafından okunduğunu kanıtlamaz.','Parts stay under the 20 MB limit and preserve message IDs and dates. Uploading a file does not prove the model read all of its content.'))}</p>
      <div class="aoActions">${preview.parts.map(part=>`<a class="aoButton" href="/api/agent-office/training/part?${new URLSearchParams({index:part.index,...(ownerId?{ownerId}:{}),profileId:profileId || state.selected})}" download>${esc(part.fileName)} · ${esc(bytes(part.bytes))}</a>`).join('')}</div>
      <h4>${esc(L('Seçilen arşiv parçalarını AI ile incele · isteğe bağlı','Review selected archive parts with AI · optional'))}</h4>
      <div class="aoScope"><label>${esc(L('Başlangıç parçası','First part'))}<input class="aoInput" type="number" name="partStart" min="1" max="${Math.max(1,preview.totalParts)}" value="${preview.range.start+1}"></label><label>${esc(L('Parça sayısı · en fazla 15','Part count · at most 15'))}<input class="aoInput" type="number" name="partCount" min="1" max="15" value="${preview.range.count || 1}"></label>${button(L('Kapsamı önizle','Preview range'),'archive-range-preview')}</div>
      <p>${esc(L('Seçili kapsam','Selected range'))}: ${preview.range.count?`${preview.range.start+1}–${preview.range.start+preview.range.count}`:'0'} / ${preview.totalParts} · ${preview.estimatedCalls} ${esc(L('tahmini AI çağrısı; dosya boyutuna göre uzun sürebilir. Normal sohbet seçili geçmişle çalışır.','estimated AI calls; large files may take a while. Normal conversations use selected history.'))}</p>
      <label>${esc(L('Arşiv analizi talebi','Archive analysis request'))}<textarea name="task" class="aoInput" rows="3" maxlength="4000">${esc(L('Kararları, açık görevleri ve tarih/kapsamı dikkate alarak olası çelişkileri kaynak kimlikleriyle özetle.','Summarize decisions, open tasks and possible contradictions using dates, scope and source IDs.'))}</textarea></label>
      <label><input type="checkbox" name="cost">${esc(L('Gösterilen çağrı sayısı ve kapsamla arşiv analizini başlatmayı onaylıyorum','I approve archive analysis with the displayed call count and scope'))}</label>`;
    const modal=dialog(L('Arşiv aktarım önizlemesi','Archive transfer preview'),body,preview.parts.length?async modal=>{
      if(!checked(modal,'cost'))throw{code:'OFFICE_COST_APPROVAL_REQUIRED'};
      if(Number(value(modal,'partStart'))!==preview.range.start+1||Number(value(modal,'partCount'))!==preview.range.count)throw{code:'OFFICE_PREVIEW_CHANGED'};
      const result=await root.BuyerLogAI.runAgentOffice({archive:true,payload:{...request,fingerprint:preview.fingerprint,maxCalls:preview.estimatedCalls,confirmed:true,task:value(modal,'task'),lang:en()?'en':'tr'},
        onProgress:event=>{modal.querySelector('[data-ao-modal-error]').textContent=event.phase==='archive-part'?`${event.index+1}/${event.total}`:L('Arşiv inceleniyor…','Reviewing the archive…');}});
      state.pane='actions';state.progress=L('Arşiv özeti iş kayıtlarına eklendi.','Archive summary was added to job records.');state.archivePreview=null;return result;
    }:null,L('Onayla ve arşivi incele','Approve and review archive'));
    modal.querySelector('[data-ao-action="archive-range-preview"]').addEventListener('click',async event=>{event.currentTarget.disabled=true;try{await archiveDialog(ownerId,profileId,{startPart:Number(value(modal,'partStart'))-1,partCount:Number(value(modal,'partCount'))});}catch(err){modal.querySelector('[data-ao-modal-error]').textContent=errorText(err);event.currentTarget.disabled=false;}});
  }
  async function publishDialog(){const agent=profile();if(!agent)return;const memories=state.data.memory.filter(item=>item.profileId===agent.id&&item.shareable&&item.approved&&item.active&&item.type!=='inference'&&(!item.expiresAt||Date.parse(item.expiresAt)>Date.now()));
    dialog(L('Agent paylaşım önizlemesi','Agent sharing preview'),`<h4>${esc(agent.name)}</h4><p class="aoTraining">${esc(agent.instructions)}</p>${memories.map(item=>`<p>${esc(item.text)}</p>`).join('')}
      <p class="aoNote">${esc(L('Yalnız bu talimatlar ve yukarıdaki paylaşıma açık hafıza katalogda yayınlanır. Sohbetler ve yetkiler kopyalanmaz. Özel eğitim arşivi moderatör kanalında ayrıca saklanır.','Only these instructions and the shared memories above are published in the catalog. Conversations and permissions are not copied. Private training is separately retained in the moderator channel.'))}</p>
      <label><input type="checkbox" name="confirm">${esc(L('Bu içeriğin diğer Buyer Log kullanıcılarına açılmasını onaylıyorum','I approve sharing this content with other Buyer Log users'))}</label>`,async modal=>{if(!checked(modal,'confirm'))throw{code:'OFFICE_APPROVAL_REQUIRED'};await api(`/profiles/${agent.id}/publish`,{confirmed:true});state.catalog=(await api('/catalog')).catalog;state.pane='catalog';},L('Katalogda paylaş','Publish to catalog'));
  }
