      <details><summary>${esc(L('Filtre ve otomasyon kodunu incele','Inspect filters and automation code'))}</summary><pre class="aoTraining">${esc(job?.proposedAutomation?.code || JSON.stringify(preview.conditions,null,2))}</pre></details>
